/** 
 * Returns an immutable map for which the  {@link Map#values} are the givenelements in the given order, and each key is the product of invoking a supplied function on its corresponding value.
 * @param values the values to use when constructing the {@code Map}
 * @param keyFunction the function used to produce the key for each value
 * @return a map mapping the result of evaluating the function {@code keyFunction} on each value in the input collection to that value
 * @throws IllegalArgumentException if {@code keyFunction} produces the samekey for more than one value in the input collection
 * @throws NullPointerException if any elements of {@code values} is null, orif  {@code keyFunction} produces {@code null} for any value
 * @since 10.0
 */
public static <K,V>ImmutableMap<K,V> uniqueIndex(Iterator<V> values,Function<? super V,K> keyFunction){
  checkNotNull(keyFunction);
  ImmutableMap.Builder<K,V> builder=ImmutableMap.builder();
  while (values.hasNext()) {
    V value=values.next();
    builder.put(keyFunction.apply(value),value);
  }
  try {
    return builder.build();
  } catch (IllegalStateException | IllegalArgumentException e) {
    throw e;
  }
}
